\label{thm:main}
The non-adaptive test design and decoding outlined in Section \ref{sec:test_design} has the following performance:
\begin{enumerate}[label=\alph*)]
  \item  
  The probability of error is at most $\varepsilon$; 
  \label{thm1:item1}
  \item  \label{thm1:item3}
  The number of tests $T$ satisfies
  \begin{align}
  \label{eq:thm:T:ub}

    T \leq 376017  {P_{min}({{q}^*})}  {H(f)} d\log \left( \frac{2n}{\varepsilon } \right)+1 \leq 376017 {H(f)} d\log\left( \frac{2n}{\varepsilon} \right)+1;
  \end{align}
  \item 
  The test design parameter ${{q}^*}$ in \eqref{eq:def:cpn} can be efficiently approximated in ${\cal O}(d^7 \log^2(d))$ time; \label{thm1:item4}
  \item  
  The computation complexity of decoding is ${\cal O} \left( n{H(f)} d  \log \left( \frac{n}{\varepsilon} \right) \right)$. \label{thm1:item2}
\end{enumerate}

Note that for a pool size of ${\chi}$, the quantities ${\mu}({\chi})$ and ${\sigma^{2}}({\chi})$, defined respectively as
\begin{equation}
\label{eq:def:u_v_x}
\begin{aligned}
        {\mu}({\chi}) &\coloneqq \sum\limits_{{a}=0}^{d} \frac{\binom{d}{{a}}\binom{n-d}{{\chi}-{a}}}{\binom{n}{{\chi}}} f({a}), \\ 
    {\sigma^{2}}({\chi}) &\coloneqq \sum\limits_{{a}=0}^{d} \frac{\binom{d}{{a}}\binom{n-d}{{\chi}-{a}}}{\binom{n}{{\chi}}} (f({a})-{\mu}({\chi}))^2, 
\end{aligned}
\end{equation}
\noindent correspond respectively to (the hypergeometrically weighted) mean and variance of the measurement function $f(\cdot)$, given that the pool-size is ${\chi}$.

\begin{customdef}{9}
For test function $f(\cdot)$ and ${\chi}\in \{0,1,\dots, n\}$, we define the concentration parameter ${h(f)}$ of $f(\cdot)$ as 
\begin{align}
\label{eq:def:concen:para}
    {h(f)}:=\min_{{\chi}\in \{1,\dots,n-1\}}\frac{{\mu}({\chi})\left(1-{\mu}({\chi})\right)}{{\sigma^{2}}({\chi})},
\end{align}

 \label{thm:converse}
For any non-adaptive group testing algorithm that ensures a reconstruction error of at most $\varepsilon$, the number of tests $T$ must satisfy  
\begin{equation}
\label{eq:T:lower:bound}
    T \geq \frac{1}{\log e} {h(f)} \left( (1-\varepsilon)\log\binom{n}{d} - 1 \right).
\end{equation}

\label{remark:lb}
Note also that for any test function ${h(f)}\geq 1$. This is because $f(a)\leq 1$ for all $a$, so using the identity  $(f({a}) - {\mu}({\chi}))^2=f^2({a}) +{\mu}^2({\chi})-2f({a}){\mu}({\chi})$, we have that for all ${\chi}$,
\begin{align*}
{\sigma^{2}}({\chi}) =\sum\limits_{{a}=0}^{d} \frac{\binom{d}{{a}}\binom{n-d}{{\chi}-{a}}}{\binom{n}{{\chi}}} f^2({a})-{\mu}^2({\chi})\leq \sum\limits_{{a}=0}^{d} \frac{\binom{d}{{a}}\binom{n-d}{{\chi}-{a}}}{\binom{n}{{\chi}}} f({a})-{\mu}^2({\chi})={\mu}({\chi})\left(1-{\mu}({\chi})\right).
\end{align*}
Hence the lower bound in \eqref{eq:T:lower:bound} scales as $ \Omega \left(\log\binom{n}{d}\right)$, which in turns scales as $ \Omega \left(d\log\left(\frac {n} {d}\right)\right)$. However, as noted in Section~\ref{subsec:comp} (see Corollary~\ref{coro:special:cases}.\ref{coro_linear} below), the bound ${h(f)} \geq 1$ is in general loose -- there exist test functions  for which ${h(f)}$ can be as large as $\Omega(d)$. Hence, due to the ${h(f)}$ term in~\eqref{eq:T:lower:bound}, this impossibility result may scale as $\Omega \left(d^2\log\left(\frac {n} {d}\right)\right)$, which is a strict tightening of the information-theoretic lower bounds $\Omega \left(d\log\left(\frac {n} {d}\right)\right)$ extant in the literature (see for instance~\cite{sid2014}).

\label{coro:special:cases}
Consider the sparse regime $d=n^\theta, 0\leq\theta <1$.
\begin{enumerate}[label=\alph*)]
    \item \label{coro_classical}For the classical group testing measurement function $f(\cdot)$ given in \eqref{f(x)_classical}, both the ${H(f)}$ and ${h(f)}$ functionals equal $1$, enabling us to recover the well-known fact (see for instance~\cite{sid2014}) that the sample-complexity of classical group-testing is $\Theta(d\log n)$ 
    \item \label{coro_threshold}For the threshold test function, i.e., for some $\ell\in\{0,\dots, d-1\}$, 
\begin{equation} 
\label{eq:threshold:function}
    f(x) = 
    \left\{
    \begin{array}{ll}
    0 & \text{if} \; x \le {\ell}, \\
    1 & \text{if} \; x > {\ell},
    \end{array} 
    \right.
\end{equation}
both the upper bound on the number of tests required for $(1-\varepsilon)$-reliable recovery in Theorem \ref{thm:main} and the corresponding lower bound in Theorem \ref{thm:converse} scale as $\Theta \left(d\log n\right)$. {To the best of our knowledge this is the first order-wise tight characterization of the optimal sample-complexity of threshold group testing.}
\item \label{coro_linear}For the ``linear" test function, i.e., 
\begin{equation}
\label{eq:linear:function}
    f(x) = \frac{x}{d}, \quad x\in\{0,\dots,d\},
\end{equation} 
the upper bound on the number of tests required for $(1-\varepsilon)$-reliable recovery in Theorem~\ref{thm:main} matches (order-wise) the lower bound in Theorem \ref{thm:converse},  both scaling as $\Theta \left(d^2\log n\right)$. Hence, by Lemma~\ref{lem:sensi:para:bound}, this test function is essentially extremal in its sample complexity. 
\end{enumerate}

